package net.civeira.phylax.feature.access.userscopeconsent.infrastructure.event;

import jakarta.enterprise.context.ApplicationScoped;
import jakarta.enterprise.event.Event;
import lombok.RequiredArgsConstructor;
import net.civeira.phylax.feature.access.userscopeconsent.domain.UserScopeConsent;
import net.civeira.phylax.feature.access.userscopeconsent.domain.event.UserScopeConsentEvent;

@ApplicationScoped
@RequiredArgsConstructor
public class UserScopeConsentEventDispatcher {

  /**
   * @autogenerated EventDispatcherGenerator
   */
  private final Event<UserScopeConsentEvent> emitter;

  /**
   * @autogenerated EventDispatcherGenerator
   * @param entity
   */
  public void dispatch(final UserScopeConsent entity) {
    entity.getRecordedEvents().forEach(emitter::fire);
  }
}
